/** Original Frog-Out rubbery croaks and pond percussion. No external recordings or music. */
export type Cue='jump'|'charge'|'build'|'fire'|'attach'|'miss'|'tension'|'impact'|'infect'|'transform'|'reveal'|'count'|'go'|'last'|'round'|'win'|'ui'|'freeze'|'rescue'|'magnet'|'wind'|'boing'|'teleport'|'bubble_pop'|'bubble_in'|'bubble_tap'|'sticky'|'crack'|'ball_thump'|'swap_warn';
type Note=[number,number,number,number?];
export const SOUNDS:Record<Cue,{cooldown:number;important?:boolean;ambience?:boolean;noise?:{length:number;cutoff:number;gain:number};type:OscillatorType;notes:Note[]}>= {
 jump:{cooldown:100,type:'sine',notes:[[170,460,.12]]},
 charge:{cooldown:220,type:'triangle',notes:[[95,650,.18],[340,95,.18,.07]]},
 build:{cooldown:330,type:'sine',notes:[[95,190,.10]]},
 fire:{cooldown:110,type:'sine',notes:[[1100,95,.13]]},
 attach:{cooldown:180,type:'triangle',notes:[[680,130,.09],[210,95,.08,.035]]},
 miss:{cooldown:200,type:'sine',notes:[[380,75,.13]]},
 tension:{cooldown:850,type:'sine',notes:[[85,145,.10]]},
 impact:{cooldown:200,type:'triangle',notes:[[170,48,.09]]},
 infect:{cooldown:240,important:true,noise:{length:.14,cutoff:2300,gain:.08},type:'triangle',notes:[[330,75,.17],[150,65,.22,.085]]},
 transform:{cooldown:350,type:'sine',notes:[[95,185,.17]]},
 reveal:{cooldown:700,important:true,type:'triangle',notes:[[110,70,.20],[190,65,.25,.13]]},
 count:{cooldown:500,important:true,type:'sine',notes:[[600,180,.075]]},
 go:{cooldown:700,important:true,type:'triangle',notes:[[180,600,.12],[420,110,.20,.09]]},
 last:{cooldown:900,important:true,type:'sine',notes:[[280,140,.15],[420,180,.20,.16]]},
 round:{cooldown:800,important:true,type:'sine',notes:[[220,330,.13],[330,440,.14,.11],[440,220,.21,.23]]},
 win:{cooldown:1800,important:true,type:'triangle',notes:[[523.25,523.25,.16],[659.25,659.25,.16,.17],[783.99,783.99,.18,.34],[1046.5,1046.5,.70,.53],[523.25,523.25,.65,.53],[659.25,659.25,.65,.53],[783.99,783.99,.65,.53]]},
 freeze:{cooldown:200,important:true,type:'sine',notes:[[1350,2300,.12],[1850,700,.17,.05]]},
 rescue:{cooldown:240,important:true,type:'sine',notes:[[700,1450,.13],[1000,2100,.12,.06]]},
 magnet:{cooldown:250,type:'sine',notes:[[310,1300,.13],[1250,650,.10,.07]]},
 wind:{cooldown:450,ambience:true,type:'sine',notes:[],noise:{length:.55,cutoff:1300,gain:.065}},
 boing:{cooldown:180,type:'triangle',notes:[[80,580,.16],[440,100,.20,.07]]},
 teleport:{cooldown:350,type:'sine',notes:[[240,1500,.12],[1450,220,.15,.10],[560,850,.10,.22]]},
 bubble_pop:{cooldown:150,type:'sine',notes:[[900,110,.065],[150,550,.07,.03]],noise:{length:.045,cutoff:3500,gain:.055}},
 bubble_in:{cooldown:250,type:'sine',notes:[[140,620,.16]]},
 bubble_tap:{cooldown:110,type:'sine',notes:[[300,510,.045]]},
 sticky:{cooldown:220,type:'triangle',notes:[[650,95,.11],[120,260,.08,.05]]},
 crack:{cooldown:300,type:'triangle',notes:[[190,65,.07]],noise:{length:.08,cutoff:2100,gain:.045}},
 ball_thump:{cooldown:350,type:'triangle',notes:[[140,45,.10]]},
